cd /tmp/ElementTest

# Create the test file
cat > ElementUITest.m << 'EOF'
#import <XCTest/XCTest.h>

@interface ElementUITest : XCTestCase
@end

@implementation ElementUITest

- (void)testOpenCreateRoomMenu {
    XCUIApplication *app = [[XCUIApplication alloc] init];
    [app launch];

    // Wait for app to load
    [NSThread sleepForTimeInterval:2.0];

    // Try to find the compose/create button by accessibility label
    XCUIElement *createButton = app.buttons[@"Create"];
    if (createButton.exists) {
        [createButton tap];
    } else {
        // Try other possible labels
        XCUIElement *composeButton = app.buttons[@"Compose"];
        if (composeButton.exists) {
            [composeButton tap];
        } else {
            // Try by coordinates if we find the button visually
            XCUICoordinate *coord = [app coordinateWithNormalizedOffset:CGPointMake(0.95, 0.95)];
            [coord tap];
        }
    }
}

@end
EOF

