#include <Cocoa/Cocoa.h>
#include <Quartz/Quartz.h>
#include <stdio.h>

int main() {
    // Try to find the Simulator window
    NSArray *windows = CFBridgingRelease(CGWindowListCopyWindowInfo(kCGWindowListOptionAll, kCGNullWindowID));

    for (NSDictionary *window in windows) {
        NSString *windowName = window[(id)kCGWindowName];
        NSString *appName = window[(id)kCGWindowOwnerName];

        if ([appName containsString:@"Simulator"]) {
            printf("Found Simulator window: %s\n", [windowName UTF8String]);
            printf("App: %s\n", [appName UTF8String]);

            // Get window bounds
            NSDictionary *bounds = window[(id)kCGWindowBounds];
            printf("Bounds: %s\n", [[bounds description] UTF8String]);

            // Try to click at the button position
            // The button should be at approximately (670, 1740) in simulator coordinates
            // We need to convert this to screen coordinates
            break;
        }
    }

    return 0;
}
EOF

